def write_new(path, data):
    if path.exists():
        raise FileExistsError(f'Preserved endpoint exists: {path}; create a new version.')
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')

def main():
    sources=[]
    for sid,authors,year,title,url,depth,locator,observation,witness in SOURCES:
        row=dict(id=sid,authors=authors,year=year,title=title,url=url,access_depth=depth,
                 observation_id=sid+'-O1',locator=locator,observation=observation,
                 as_of='2026-10-11',raw_witness=None)
        if witness and (RAW/(witness+'.acquisition.json')).exists():
            a=json.loads((RAW/(witness+'.acquisition.json')).read_text(encoding='utf-8'))
            row['raw_witness']={k:a[k] for k in ['local_path','sha256','bytes','retrieved_utc']}
        sources.append(row)
    write_new(BASE/'sources-v1.json', {'scope':'Authored observations and source pointers; source witnesses local-only', 'sources':sources})
    targets=[]
    for tid,name,bbox,priority,origin,mechanism,cites,search,rival,test,control in TARGETS:
        targets.append(dict(id=tid,name=name,bbox_lonlat=bbox,bbox_definition='Hand-drawn editorial planning rectangle,0.1-degree precision; overlapping, not measured site boundary',priority_class=priority,origin=origin,missingness_mechanism=mechanism,source_ids=cites.split(','),target=search,competing_explanation=rival,falsification_test=test,comparison_stratum=control,field_feasibility='not assessed; permits, local collaboration, access and recent land use require verification',status='exploratory search hypothesis; no new discovery',predicted_site_count=None,predicted_area_ha=None,predicted_artifact_total=None))
    write_new(BASE/'candidates-v1.json',{'as_of':'2026-10-11','priority_classes':{'A':'Archaeological or published feature follow-up','B':'Preservation/visibility comparison with regional archaeological support','C':'Chronology-first or cultural-attribution-first exploration'},'targets':targets})
    print(f'Wrote {len(sources)} sources and {len(targets)} proposed sampling windows.')

if __name__=='__main__':
    main()
